from heapq import heappop, heappush

def findRange(lists):
	if not lists:
		return (-1, -1)
	high = -99999
	p = (0, 99999)
	q = []
	for i in range(len(lists)):
		if not lists[i]:
			return (-1, -1)
		heappush(q, (lists[i][0], i, 0))
		high = max(high, lists[i][0])
	while True:
		top = heappop(q)
		low = top[0]
		i = top[1]
		j = top[2]
		if high - low < p[1] - p[0]:
			p = (low, high)
		if j == len(lists[i]) - 1:
			return p
		heappush(q, (lists[i][j + 1], i, j + 1))
		high = max(high, lists[i][j + 1])
from collections import deque

def levelorder(root):
	if root == None:
		return (-1, -1)
	q = deque([])
	q.append(root)
	ans = []
	while len(q) > 0:
		n = len(q)
		st = []
		for i in range(1, n + 1):
			temp = q.popleft()
			st.append(temp.data)
			if temp.left:
				q.append(temp.left)
			if temp.right:
				q.append(temp.right)
		ans.append(st)
	return ans

class Solution:

	def shortestRange(self, root):
		ans = levelorder(root)
		return findRange(ans)
